/** Build the original educational skin cross-section (an original schematic
 *  model generated by code — no external geometry):
 *
 *    epidermis / dermis / hypodermis slabs with a wavy dermal-epidermal
 *    junction (rete ridges) and dermal papillae
 *    hypodermal fat lobules, a hair with follicle, papilla, sebaceous gland
 *    and arrector pili muscle, an eccrine sweat gland with its duct,
 *    capillary loops rising into the papillae plus superficial/deep plexuses,
 *    free nerve endings and a tactile corpuscle
 *
 *  Parts keep the atlas manifest shape (positions/normals/indices/one chunk)
 *  so the existing viewer, picking, search, and per-system loading work
 *  unchanged. Structures are enlarged for visibility: the section represents
 *  roughly 3 mm of skin shown at body scale (~250x). Run
 *  `node scripts/build-skin-model.mjs` to regenerate. */
import fs from 'node:fs';
import {gzipSync} from 'node:zlib';
const base=new URL('../public/models/',import.meta.url);

// ---------- mesh helpers ----------
const mag=v=>Math.hypot(v[0],v[1],v[2]);
const norm=v=>{const l=mag(v)||1;return [v[0]/l,v[1]/l,v[2]/l];};
const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const sub=(a,b)=>[a[0]-b[0],a[1]-b[1],a[2]-b[2]];

class Mesh{
 constructor(){this.v=[];this.i=[];}
 vertex(p){this.v.push(p[0],p[1],p[2]);return this.v.length/3-1;}
 quad(a,b,c,d){this.i.push(a,b,c,a,c,d);}
 tri(a,b,c){this.i.push(a,b,c);}
 build(){return {positions:new Float32Array(this.v),indices:new Uint32Array(this.i)};}
}
const normalsOf=(pos,idx)=>{
 const n=new Float32Array(pos.length);
 for(let k=0;k<idx.length;k+=3){
  const a=idx[k]*3,b=idx[k+1]*3,c=idx[k+2]*3;
  const u=[pos[b]-pos[a],pos[b+1]-pos[a+1],pos[b+2]-pos[a+2]];
  const w=[pos[c]-pos[a],pos[c+1]-pos[a+1],pos[c+2]-pos[a+2]];
  const f=cross(u,w);
  for(const j of [a,b,c]){n[j]+=f[0];n[j+1]+=f[1];n[j+2]+=f[2];}
 }
 for(let k=0;k<n.length;k+=3){const l=mag([n[k],n[k+1],n[k+2]])||1;n[k]/=l;n[k+1]/=l;n[k+2]/=l;}
 return new Int16Array(Array.from(n,x=>Math.round(x*32767)));
};
/** Height-field slab: top/bottom surfaces sampled on a grid, stitched at the
 *  boundary. topFn/bottomFn are (x,z)=>y. */
const slab=(x0,x1,z0,z1,nx,nz,topFn,bottomFn)=>{
 const m=new Mesh();
 const top=[],bottom=[];
 for(let iz=0;iz<=nz;iz++)for(let ix=0;ix<=nx;ix++){
  const x=x0+(x1-x0)*ix/nx,z=z0+(z1-z0)*iz/nz;
  top.push(m.vertex([x,topFn(x,z),z]));
  bottom.push(m.vertex([x,bottomFn(x,z),z]));
 }
 const id=(ix,iz)=>iz*(nx+1)+ix;
 for(let iz=0;iz<nz;iz++)for(let ix=0;ix<nx;ix++){
  const a=id(ix,iz),b=id(ix+1,iz),c=id(ix+1,iz+1),d=id(ix,iz+1);
  m.quad(a,d,c,b);       // top, facing up
  m.quad(bottom[a],bottom[b],bottom[c],bottom[d]); // bottom, facing down
 }
 // boundary walls
 for(let ix=0;ix<nx;ix++){
  const pairs=[[id(ix,0),id(ix+1,0)],[id(ix+1,nz),id(ix,nz)]];
  for(const [p,q] of pairs){m.quad(top[p],top[q],bottom[q],bottom[p]);}
 }
 for(let iz=0;iz<nz;iz++){
  const pairs=[[id(nx,iz),id(nx,iz+1)],[id(0,iz+1),id(0,iz)]];
  for(const [p,q] of pairs){m.quad(top[p],top[q],bottom[q],bottom[p]);}
 }
 return m.build();
};
/** Ellipsoid. */
const sphere=(c,r,seg=12,ring=8)=>{
 const m=new Mesh();
 for(let j=0;j<=ring;j++){
  const phi=-Math.PI/2+Math.PI*j/ring;
  for(let k=0;k<=seg;k++){
   const th=2*Math.PI*k/seg;
   m.vertex([c[0]+r[0]*Math.cos(phi)*Math.cos(th),c[1]+r[1]*Math.sin(phi),c[2]+r[2]*Math.cos(phi)*Math.sin(th)]);
  }
 }
 const id=(j,k)=>j*(seg+1)+k;
 for(let j=0;j<ring;j++)for(let k=0;k<seg;k++){
  const a=id(j,k),b=id(j,k+1),c=id(j+1,k+1),d=id(j+1,k);
  if(j===0)m.tri(a,b,c);
  else if(j===ring-1)m.tri(a,d,c);
  else m.quad(a,b,c,d);
 }
 return m.build();
};
/** Tube along a polyline with a radius per point. */
const tube=(pts,radii,seg=8)=>{
 const m=new Mesh();
 const rings=[];
 for(let i=0;i<pts.length;i++){
  const prev=pts[Math.max(0,i-1)],next=pts[Math.min(pts.length-1,i+1)];
  const t=norm(sub(next,prev));
  const up=Math.abs(t[1])<0.9?[0,1,0]:[1,0,0];
  const u=norm(cross(t,up)),w=norm(cross(t,u));
  const ring=[];
  for(let k=0;k<seg;k++){
   const th=2*Math.PI*k/seg;
   const dir=[u[0]*Math.cos(th)+w[0]*Math.sin(th),u[1]*Math.cos(th)+w[1]*Math.sin(th),u[2]*Math.cos(th)+w[2]*Math.sin(th)];
   ring.push(m.vertex([pts[i][0]+dir[0]*radii[i],pts[i][1]+dir[1]*radii[i],pts[i][2]+dir[2]*radii[i]]));
  }
  rings.push(ring);
 }
 for(let i=0;i<pts.length-1;i++)for(let k=0;k<seg;k++){
  const a=rings[i][k],b=rings[i][(k+1)%seg],c=rings[i+1][(k+1)%seg],d=rings[i+1][k];
  m.quad(a,b,c,d);
 }
 // caps
 for(const [ringIdx,center] of [[0,pts[0]],[pts.length-1,pts[pts.length-1]]]){
  const c=m.vertex(center);
  for(let k=0;k<seg;k++){
   const a=rings[ringIdx][k],b=rings[ringIdx][(k+1)%seg];
   if(ringIdx===0)m.tri(c,b,a);else m.tri(c,a,b);
  }
 }
 return m.build();
};

// ---------- section layout ----------
const surfaceY=(x,z)=>0.452+0.003*Math.sin(x*13+1.3)*Math.sin(z*9+0.7);
const junctionY=(x,z)=>0.415+0.013*Math.sin(x*42+0.5)*Math.cos(z*26);

const parts=[],concepts=[];
const bin=new (class{constructor(){this.chunks=[];this.cur=[];this.bytes=0;}
 pad(){const p=(4-this.bytes%4)%4;if(p){this.cur.push(Buffer.alloc(p));this.bytes+=p;}}
 add(view){this.pad();const offset=this.bytes;this.cur.push(Buffer.from(view.buffer,view.byteOffset,view.byteLength));this.bytes+=view.byteLength;return offset;}
 flush(){if(!this.bytes)return;fs.writeFileSync(new URL(`skin-crosssection-${this.chunks.length}.bin`,base),Buffer.concat(this.cur));this.chunks.push({url:`/models/skin-crosssection-${this.chunks.length}.bin`,bytes:this.bytes});this.cur=[];this.bytes=0;}})();
const addPart=(id,name,system,mesh)=>{
 const normals=normalsOf(mesh.positions,mesh.indices);
 const lo=[Infinity,Infinity,Infinity],hi=[-Infinity,-Infinity,-Infinity];
 for(let k=0;k<mesh.positions.length;k+=3)for(let a=0;a<3;a++){lo[a]=Math.min(lo[a],mesh.positions[k+a]);hi[a]=Math.max(hi[a],mesh.positions[k+a]);}
 parts.push({id,name,conceptId:`SKIN:c-${id}`,system,chunk:0,
  positions:bin.add(mesh.positions),normals:bin.add(normals),indices:bin.add(mesh.indices),
  vertexCount:mesh.positions.length/3,indexCount:mesh.indices.length,bounds:[lo,hi]});
 concepts.push({id:`SKIN:c-${id}`,name,elements:[id]});
};

addPart('dermis','Dermis','integumentary',
 slab(-0.45,0.45,-0.15,0.15,64,22,junctionY,()=>0.185));
addPart('epidermis','Epidermis','integumentary',
 slab(-0.45,0.45,-0.15,0.15,64,22,surfaceY,junctionY));
addPart('hypodermis','Hypodermis','integumentary',
 slab(-0.45,0.45,-0.15,0.15,32,12,()=>0.185,()=>0));
// fat lobules packed into the hypodermis
{
 const m=new Mesh();
 for(let gx=-0.38;gx<=0.38;gx+=0.092)for(let gz=-0.11;gz<=0.11;gz+=0.072){
  const jx=gx+0.012*Math.sin(gx*57+gz*31),jz=gz+0.01*Math.cos(gx*23+gz*71);
  const jy=0.085+0.045*Math.sin(gx*17+3);
  const s=sphere([jx,Math.max(0.05,Math.min(0.145,jy)),jz],[0.031+0.005*Math.sin(gx*41),0.028,0.03],10,7);
  const off=m.v.length/3;
  m.v.push(...s.positions);
  for(const idx of s.indices)m.i.push(idx+off);
 }
 addPart('fat-lobules','Fat lobules','integumentary',m.build());
}
// hair follicle + bulb, papilla, shaft
const folliclePts=[[0.203,0.457,0],[0.209,0.395,0],[0.219,0.325,0],[0.23,0.265,0],[0.238,0.238,0]];
addPart('hair-follicle','Hair follicle','integumentary',
 tube(folliclePts,[0.014,0.015,0.017,0.019,0.02]));
addPart('hair-bulb','Hair bulb','integumentary',sphere([0.239,0.232,0],[0.024,0.021,0.024],12,8));
addPart('hair-papilla','Hair papilla','integumentary',sphere([0.241,0.224,0],[0.011,0.012,0.011],10,7));
addPart('hair-shaft','Hair shaft','integumentary',
 tube([[0.201,0.45,0],[0.196,0.52,0],[0.188,0.585,0]],[0.0062,0.0048,0.0028]));
addPart('sebaceous-gland','Sebaceous gland','integumentary',(()=>{
 const m=new Mesh();
 for(const [cx,cy,cz,r] of [[0.171,0.35,0.009,0.013],[0.163,0.327,-0.004,0.012],[0.175,0.313,0.007,0.011]]){
  const s=sphere([cx,cy,cz],[r,r*0.85,r],9,6);
  const off=m.v.length/3;m.v.push(...s.positions);
  for(const idx of s.indices)m.i.push(idx+off);
 }
 return m.build();
})());
addPart('arrector-pili','Arrector pili muscle','muscular',
 tube([[0.163,0.3,0],[0.24,0.355,0.008],[0.325,0.417,0]],[0.005,0.0065,0.004],6));
// eccrine sweat gland: coiled secretory portion + duct to a pore
{
 const pts=[];const turns=2.3,N=64;
 for(let k=0;k<=N;k++){
  const t=k/N*turns*2*Math.PI;
  pts.push([-0.27+0.027*Math.cos(t),0.235+0.006*Math.sin(2*t)*0.3+0.004*(k/N),0.02+0.027*Math.sin(t)]);
 }
 addPart('eccrine-sweat-gland','Eccrine sweat gland','integumentary',tube(pts,Array(N+1).fill(0.0058),7));
 addPart('sweat-duct','Sweat duct','integumentary',
  tube([[-0.27,0.262,0.02],[-0.262,0.33,-0.008],[-0.248,0.405,-0.028],[-0.244,surfaceY(-0.244,-0.03)+0.001,-0.03]],[0.0038,0.0034,0.003,0.0028],6));
}
// vasculature: papillary loops + superficial (arterial) and deep (venous) plexuses
{
 const m=new Mesh();
 for(const lx of [-0.36,-0.21,-0.06,0.09,0.33,0.41]){
  const j=junctionY(lx,0.02);
  const loop=tube([[lx-0.009,0.396,0.02],[lx-0.006,j+0.005,0.02],[lx,j+0.011,0.02],[lx+0.006,j+0.005,0.02],[lx+0.009,0.396,0.02]],Array(5).fill(0.0026),6);
  const off=m.v.length/3;m.v.push(...loop.positions);
  for(const idx of loop.indices)m.i.push(idx+off);
 }
 addPart('capillary-loops','Capillary loops','arterial',m.build());
 const wave=(y,z,amp)=>{const pts=[];for(let x=-0.44;x<=0.441;x+=0.036)pts.push([x,y+amp*Math.sin(x*29),z]);return pts;};
 addPart('superficial-plexus','Superficial dermal plexus','arterial',tube(wave(0.392,0.05,0.004),Array(26).fill(0.0032),6));
 addPart('deep-plexus','Deep dermal plexus','venous',tube(wave(0.212,-0.05,0.005),Array(26).fill(0.0042),6));
}
// innervation: deep trunk, branching free endings into the epidermis, corpuscle
{
 const m=new Mesh();
 const push=t=>{const off=m.v.length/3;m.v.push(...t.positions);for(const idx of t.indices)m.i.push(idx+off);};
 push(tube([[-0.06,0.02,0.05],[-0.05,0.12,0.055],[-0.04,0.25,0.06],[-0.03,0.33,0.055]],Array(4).fill(0.0036),6));
 const branchBase=[-0.035,0.36,0.055];
 for(const [dx,dz] of [[-0.05,0.02],[0.02,0.04],[0.06,-0.03],[-0.09,-0.02]]){
  const ex=branchBase[0]+dx,ez=branchBase[2]+dz;
  const j=junctionY(ex,ez);
  push(tube([[branchBase[0],branchBase[1],branchBase[2]],[ex*0.55+branchBase[0]*0.45,j-0.02,ez*0.55+branchBase[2]*0.45],[ex,j+0.006,ez],[ex+0.004,surfaceY(ex,ez)-0.004,ez+0.004]],[0.002,0.0016,0.0012,0.0008],5));
 }
 addPart('free-nerve-endings','Free nerve endings','nervous',m.build());
 addPart('tactile-corpuscle','Tactile corpuscle','nervous',sphere([0.06,junctionY(0.06,0)+0.007,-0.04],[0.019,0.0055,0.006],10,7));
}
bin.flush();

const manifest={version:'1.0',sex:'skin',source:'Original procedural educational model (this project)',
 scope:'Schematic skin cross-section, ~250x enlarged; not scan data',
 parts,concepts,chunks:bin.chunks,triangles:parts.reduce((n,p)=>n+p.indexCount/3,0)};
const jsonPath=new URL('skin-crosssection.json',base);
fs.writeFileSync(jsonPath,JSON.stringify(manifest));
const gz=gzipSync(fs.readFileSync(new URL(manifest.chunks[0].url.split('/').pop(),base)),{level:9});
manifest.chunks[0].gzip=manifest.chunks[0].url+'.gz';manifest.chunks[0].gzipBytes=gz.length;
fs.writeFileSync(new URL(manifest.chunks[0].gzip.split('/').pop(),base),gz);
fs.writeFileSync(jsonPath,JSON.stringify(manifest));
console.log(JSON.stringify({parts:parts.length,concepts:concepts.length,triangles:manifest.triangles,chunkBytes:bin.chunks[0].bytes,gzipBytes:gz.length}));
